reg_decoder_fld_t tof2_mau_stateful_alu_addrmap__salu_instr_common_fld_list[] = {
    { "salu_alu2_lo_bsrc_math", 0, 0, 0,0, 
      "Selects math output for alu2-lo B source.  This takes precedence over salu_bsrc_input" },
    { "salu_alu2_lo_math_src", 2, 1, 0,0, 
      "controls math function of alu2 lo when salu_alu2_lo_bsrc_math = 1. 0 = PHV lo 1 = PHV hi 2 = memory lo 3 = memory hi" },
    { "salu_datasize", 5, 3, 0,0, 
      "data size is 2**salu_datasize bits.  Must be 7 for 128b min/max operations" },
    { "salu_op_dual", 6, 6, 0,0, 
      "if 1, dual operation, if 0, single operation.  For 128b min/max operations, this must be programmed to 0" },
    { "salu_lmatch_sbus_listen", 9, 7, 0,0, 
      "Controls whether the stateful ALU listens to the shared Learn bus broadcast up from each ALU" },
    { "salu_match_sbus_listen", 12, 10, 0,0, 
      "Controls whether the stateful ALU listens to the shared Match bus broadcast down from each ALU" },
    { "salu_minmax_mask_ctl", 13, 13, 0,0, 
      "1 = mask comes from 32b Registerfile bits 15:0 or 7:0.  CMP ALU3 registerfile address (salu_cmp_regfile_adr) is overloaded for this purpose to save hardware 0 = mask comes from PHV[15:0] or PHV[7:0] depending on 8b vs 16b minmax" },
    { "salu_minmax_ctl", 15, 14, 0,0, 
      "When salu_minmax_enable is enabled, this controls the 128b min/max instruction 0 = 8b  min 1 = 8b  max 2 = 16b min 3 = 16b max" },
    { "salu_minmax_enable", 16, 16, 0,0, 
      "Enables 128b min/max instructions which override the state-update ALU-hi/lo outputs going to the action output" },
    { "salu_minmax_postinc_enable", 17, 17, 0,0, 
      "Enables 128b min/max instructions to perform a post-increment after finding the min/max" },
    { "salu_minmax_postdec_enable", 18, 18, 0,0, 
      "Enables 128b min/max instructions to perform a post-decrement after finding the min/max" },
    { "salu_minmax_postmod_value_ctl", 19, 19, 0,0, 
      "1 = 8b postmod value comes from PHV[23:16] for 8b minmax or PHV[15:8] for 16b minmax when salu_minmax_mask_ctl==0.  8b postmod value comes from PHV[7:0] when salu_minmax_mask_ctl==1 0 = 8b postmod value comes from 32b Registerfile bits 23:16 for 8b minmax and bits 15:8 for 16b minmax when salu_minmax_mask_ctl==1.   8b postmod value comes from registerfile bits 7:0 when salu_minmax_mask_ctl==0.  CMP ALU3 registerfile address (salu_cmp_regfile_adr) is overloaded for this purpose to save hardware" },
    { "salu_minmax_src_sel", 20, 20, 0,0, 
      "1 = Minmax operation is performed on PHV[127:0].  If the mask and/or postmod value is also contained in the PHV, then up to 3 bytes inside PHV[23:0] need to be masked out of the minmax selection.  The remaining PHV bits partake in the minmax 0 = Minmax operation is performed on the 128b RAM word." },
    { "salu_divide_enable", 21, 21, 0,0, 
      "Enables 16x16b signed divide/mod operation overriding both ALU-HI function to overload its input operands for use by the divider" },
    { "salu_sbus_learn_comb", 22, 22, 0,0, 
      "Determines how the TMatch1 and TMatch0 'learn' outputs are combined before driving the Learn shared bus. 1 = AND TMatch0/1 learn outputs together 0 = OR TMatch0/1 learn outputs together If TMatch0/1 learn output is disabled through salu_tmatch_vld_ctl, then its learn output is driven to 0" },
    { "salu_sbus_match_comb", 23, 23, 0,0, 
      "Determines how the TMatch1 and TMatch0 'match' outputs are combined before driving the Learn shared bus. 1 = AND TMatch0/1 match outputs together 0 = OR TMatch0/1 match outputs together If TMatch0/1 is disabled through salu_cmp_tmatch_enable, then its match output is driven to 0 " },
    { "salu_sbus_in_comb", 24, 24, 0,0, 
      "Determines how the sbus_match[2:0] and sbus_learn[2:0] busses are factored into predication logic. 1 = AND sbus_match/sbus_learn inputs together (useful for wide match) 0 = OR sbus_match/sbus_learn inputs" },
};
