reg_decoder_fld_t tof2_mau_match_merge_addrmap__mau_stateful_log_counter_ctl2_fld_list[] = {
    { "slog_counter_function", 2, 0, 0,0, 
      "Configures the function for each pair of push/pop stateful logging counters in the counter space. This register contains a 3b control for each pair of push/pop with the following encodings: 0: disabled 1: stateful logging (pop counter unused) 2: FIFO 3: Stack (pop counter unused) 4: Stateful Bloom Filter Clear 5-7: Reserved " },
    { "slog_instruction_width", 5, 3, 0,0, 
      "For each stateful logging counter, 3b are needed to indicate the instruction width and thus the number of address subword bits. The encoding of these 3b for each logical table is: 0: 8b  1: 16b  (or 8b  dual-width instruction) 2: 32b  (or 16b dual-width instruction) 3: 64b  (or 32b dual-width instruction) 4: 128b (or 64b dual-width instruction) 5-7: reserved " },
    { "slog_pop_event_ctl", 6, 6, 0,0, 
      "1: FIFO/Stack pop events are issued from software instructions (ignored if not configured as FIFO/Stack) 0: FIFO/Stack pop events are issued from the dataplane as configured in mau_stateful_log_counter_ctl (ignored if not configured as FIFO/Stack)" },
    { "slog_push_event_ctl", 7, 7, 0,0, 
      "1: FIFO/Stack push events are issued from software instructions (ignored if not configured as FIFO/Stack) 0: FIFO/Stack push events are issued from the dataplane as configured in mau_stateful_log_counter_ctl (ignored if not configured as FIFO/Stack)" },
    { "slog_vpn_base", 16, 8, 0,0, 
      "VPN base at which the stateful logging address counter should start counting.  This is needed when the stateful table VPN does not begin at zero, usually when a stateful table is shared across multiple logical match tables. 9b VPN is needed per stateful ALU (3 additional bits for up to 8-stage FIFO).  2 VPNs are stored per 12b register." },
    { "slog_vpn_limit", 25, 17, 0,0, 
      "VPN limit at which the stateful logging address counter should stop counting and signal an interrupt. 9b VPN is needed per stateful ALU (3b stage ID + 6b VPN.  2 VPNs are stored per 12b register. NOTE: A VPN limit value of 511 is invalid.  The maximum FIFO size is 8 stages * 48 RAMs = 384 RAMs, so this poses no limitation on the maximum fifo/stack size" },
    { "slog_watermark_ctl", 26, 26, 0,0, 
      "Controls whether watermarks monitor push or pop events. 0=push, 1=pop.  Watermarking events under software control should not be enabled." },
    { "slog_watermark_enable", 27, 27, 0,0, 
      "Enables watermarking" },
};
